/**
 * lite-sandbox for pi.
 *
 * Generated by `lite-sandbox install pi` (or `lite-sandbox launch pi`); a
 * reinstall rewrites this file, so do not edit it. It:
 *
 *  - registers lite-sandbox's MCP server (`lite-sandbox serve-mcp`), whose
 *    `mcp__lite_sandbox__bash` tool runs shell commands through the sandbox's
 *    AST validation, path boundaries and OS sandbox, in one long-lived process;
 *  - forwards each call of pi's built-in shell and file tools, and of the
 *    sandbox's bash tool, to `lite-sandbox hook`, which confines the file
 *    tools to the sandbox's paths and redirects the built-in shell; a denial
 *    blocks the call, and an "ask" (a config request, or a command the
 *    sandbox's config asks about) is put to the user in a dialog;
 *  - adds a system prompt section telling the model to use the sandbox.
 *
 * Whenever the hook cannot give an answer (it is missing, fails, or times
 * out) the call is blocked: pi itself never asks before running a tool.
 */
import { spawn } from "node:child_process";
import type { ExtensionAPI } from "@earendil-works/pi-coding-agent";

interface LiteSandboxConfig {
	/** Absolute path of the lite-sandbox binary. */
	bin: string;
	/** Register the MCP server (off in --bash-ast-hook-mode). */
	mcp: boolean;
	/** Arguments for `lite-sandbox serve-mcp`. */
	serveArgs: string[];
	/** Arguments for `lite-sandbox hook`. */
	hookArgs: string[];
	/** The tools whose calls are forwarded to the hook. */
	tools: string[];
	/** System prompt section, or "" for none. */
	directive: string;
	/** Seconds to wait for the hook before blocking the call. */
	hookTimeoutSec: number;
}

const CONFIG: LiteSandboxConfig = __LITE_SANDBOX_CONFIG__;

const SERVER_NAME = "lite-sandbox";

type Decision = { decision: "allow" | "deny" | "ask" | ""; reason: string };

/** Runs `lite-sandbox hook` on one PreToolUse event and returns its decision. */
function runHook(event: Record<string, unknown>, signal?: AbortSignal): Promise<Decision> {
	return new Promise((resolve, reject) => {
		const child = spawn(CONFIG.bin, CONFIG.hookArgs, { stdio: ["pipe", "pipe", "pipe"] });
		let stdout = "";
		let stderr = "";
		let settled = false;
		const finish = (err: Error | undefined, value?: Decision) => {
			if (settled) return;
			settled = true;
			clearTimeout(timer);
			signal?.removeEventListener("abort", onAbort);
			if (err) reject(err);
			else resolve(value as Decision);
		};
		const timer = setTimeout(() => {
			child.kill("SIGKILL");
			finish(new Error(`lite-sandbox hook did not answer within ${CONFIG.hookTimeoutSec}s`));
		}, CONFIG.hookTimeoutSec * 1000);
		const onAbort = () => {
			child.kill("SIGKILL");
			finish(new Error("lite-sandbox hook was cancelled"));
		};
		signal?.addEventListener("abort", onAbort, { once: true });

		child.stdout.setEncoding("utf8");
		child.stderr.setEncoding("utf8");
		child.stdout.on("data", (chunk: string) => (stdout += chunk));
		child.stderr.on("data", (chunk: string) => (stderr += chunk));
		child.on("error", (err) => finish(new Error(`could not run lite-sandbox hook (${CONFIG.bin}): ${err.message}`)));
		child.on("close", (code) => {
			if (code !== 0) {
				finish(new Error(`lite-sandbox hook exited with status ${code}: ${stderr.trim()}`));
				return;
			}
			if (stdout.trim() === "") {
				// The hook defers: nothing for the sandbox to enforce.
				finish(undefined, { decision: "", reason: "" });
				return;
			}
			try {
				const out = JSON.parse(stdout).hookSpecificOutput ?? {};
				finish(undefined, {
					decision: out.permissionDecision ?? "",
					reason: out.permissionDecisionReason ?? "",
				});
			} catch (err) {
				finish(new Error(`lite-sandbox hook printed an unreadable decision: ${String(err)}`));
			}
		});
		child.stdin.on("error", () => {
			// The hook exited before reading its input; "close" reports it.
		});
		child.stdin.end(JSON.stringify(event));
	});
}

export default function liteSandbox(pi: ExtensionAPI) {
	if (CONFIG.mcp) {
		pi.registerMcpServer(SERVER_NAME, {
			command: CONFIG.bin,
			args: CONFIG.serveArgs,
			// Declared to the model like a built-in tool: it replaces the
			// built-in bash, so it is needed on almost every turn.
			exposure: "direct",
			description: "Run shell commands through lite-sandbox's validation and filesystem boundaries",
		});
	}

	pi.on("tool_call", async (event, ctx) => {
		if (!CONFIG.tools.includes(event.toolName)) return undefined;
		const { decision, reason } = await runHook(
			{
				hook_event_name: "PreToolUse",
				pi_event: "tool_call",
				cwd: ctx.cwd,
				tool_name: event.toolName,
				tool_input: event.input,
			},
			ctx.signal,
		);
		switch (decision) {
			case "deny":
				return { block: true, reason };
			case "ask": {
				if (!ctx.hasUI) {
					return {
						block: true,
						reason: `${reason}\nThis needs the user's approval, and pi is running without a UI to ask for it.`,
					};
				}
				const approved = await ctx.ui.confirm("lite-sandbox", reason);
				if (!approved) {
					return { block: true, reason: `The user declined this call.\n${reason}` };
				}
				return undefined;
			}
			default:
				return undefined;
		}
	});

	if (CONFIG.directive !== "") {
		pi.on("before_agent_start", (event) => {
			// A named section is patched into the prompt in place, keeping the
			// provider's prompt cache; replacing the whole prompt is the fallback.
			const sections = event.systemPromptOptions?.sections;
			if (sections) {
				sections[SERVER_NAME] = CONFIG.directive;
				return undefined;
			}
			return { systemPrompt: `${event.systemPrompt}\n\n${CONFIG.directive}` };
		});
	}
}
